data: {"type":"response.output_text.done","content_index":0,"item_id":"msg_060ad1f6e72cc963016aeb184e19d487d28e337e631bfb21a2","logprobs":[],"output_index":0,"sequence_number":532,"text":"<title>Coffee order</title>\n<meta name=\"idea\" content=\"Build a coffee order with live quantity and price updates\">\n<main>\n  <h1>Daybreak Coffee</h1>\n  <p>Freshly brewed, just for you.</p>\n  <nav>\n    <a href=\"#\" data-action=\"Coffee menu with drinks and prices\">Menu</a> ·\n    <a href=\"#\" data-action=\"Coffee shop order history\">Orders</a> ·\n    <a href=\"#\" data-action=\"Coffee shop account profile\">Account</a>\n  </nav>\n  <hr>\n  <h2>Your order</h2>\n  <article>\n    <h3>Oat milk latte</h3>\n    <p>Espresso, silky oat milk · $5.25</p>\n    <label for=\"size\">Size</label>\n    <select id=\"size\">\n      <option value=\"0\">Regular</option>\n      <option value=\"1\">Large (+$0.75)</option>\n    </select>\n    <label for=\"qty\">Quantity</label>\n    <input id=\"qty\" type=\"number\" min=\"1\" value=\"2\">\n  </article>\n  <article>\n    <h3>Also popular</h3>\n    <p>Cold brew · $4.50</p>\n    <button data-action=\"Cold brew details with size and customization options\">View cold brew</button>\n    <p>Butter croissant · $3.25</p>\n    <button data-action=\"Butter croissant details and add-to-order options\">View croissant</button>\n  </article>\n  <p>Subtotal: <strong id=\"total\">$10.50</strong></p>\n  <button data-action=\"Checkout screen for two oat milk lattes from Daybreak Coffee\">Checkout</button>\n  <button data-action=\"Coffee menu with drinks and prices\">Add another drink</button>\n  <script>\n    const size = document.querySelector(\"#size\"), qty = document.querySelector(\"#qty\"), total = document.querySelector(\"#total\");\n    function update() {\n      const count = Math.max(1, Number(qty.value) || 1);\n      total.textContent = (count * (5.25 + Number(size.value) * 0.75)).toLocaleString(\"en-US\", { style: \"currency\", currency: \"USD\" });\